// Un item por destinatario y canal. Cada entrada es una alerta tomada por
// alert_staff_dispatch_claim (columna `payload`).
const out = [];
for (const item of $input.all()) {
  const p = item.json.payload;
  if (!p || !p.alert_instance_id) continue;
  const channels = p.channels || {};
  for (const r of p.recipients || []) {
    const fields = { ...(p.fields || {}), 'recipient.name': r.name || '', 'clinic.name': p.clinic_name || '' };
    const base = {
      alert_instance_id: p.alert_instance_id,
      title: p.title,
      summary: p.summary,
      lines: p.lines || [],
      category_slug: p.category_slug,
      config: p.config || {},
      recipient: r,
      fields,
    };
    if (channels.in_app && r.notification) out.push({ json: { ...base, kind: 'in_app', notification_type: p.notification_type } });
    if (channels.email) out.push({ json: {
      ...base, kind: 'email', template: p.email_template, template_id: p.email_template_id,
      channel_enabled: p.email_channel_enabled !== false,
    } });
    if (channels.whatsapp) out.push({ json: {
      ...base, kind: 'whatsapp', template: p.whatsapp_template, template_id: p.whatsapp_template_id,
      channel_enabled: p.whatsapp_channel_enabled !== false,
    } });
  }
}
return out;

// Arma el email de un aviso al equipo. Nunca lanza: devuelve ok:false con el
// motivo para dejarlo en alert_actions. Los mismos interruptores que el envío a
// pacientes ("Alert Email Auto-Send").
const j = $json;
const cfg = j.config || {};
const fail = (reason) => [{ json: { ...j, ok: false, reason } }];
const who = j.recipient?.name || j.recipient?.user_id;

if (!cfg.email_auto_send_enabled) {
  return fail('Los emails automáticos de alertas están apagados (alert_email_auto_send_enabled)');
}
if (!j.channel_enabled) {
  return fail(`El canal email está deshabilitado para la categoría "${j.category_slug}"`);
}
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const to = j.recipient?.email;
if (!to || !EMAIL_RE.test(to)) return fail(`${who}: sin email válido`);
if (j.recipient?.email_bounced) return fail(`${who}: el email ${to} rebotó`);
if (cfg.email_test_mode) {
  const whitelist = String(cfg.email_test_whitelist || '').split(',').map((e) => e.trim().toLowerCase()).filter(Boolean);
  if (!whitelist.includes(to.toLowerCase())) return fail(`Modo prueba de email: ${to} no está en la lista permitida`);
}
if (j.template_id && !j.template) return fail(`La plantilla de email ${j.template_id} está inactiva o no existe`);

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fill = (text, html) => String(text || '').replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => (k in j.fields ? (html ? esc(j.fields[k]) : j.fields[k]) : ''));
let subject;
let html;
if (j.template && (j.template.body_html || j.template.body_text)) {
  subject = fill(j.template.subject || j.title, false);
  html = j.template.body_html ? fill(j.template.body_html, true) : `<p>${esc(fill(j.template.body_text, false))}</p>`;
} else {
  const lines = (j.lines || []).filter((l) => l && l.value);
  subject = j.title;
  html = [
    `<p>Hola ${esc(j.fields['recipient.name'])},</p>`,
    `<p><strong>${esc(j.title)}</strong></p>`,
    lines.length
      ? `<p>${lines.map((l) => `${esc(l.label)}: ${esc(l.value)}`).join('<br>')}</p>`
      : (j.summary ? `<p>${esc(j.summary)}</p>` : ''),
    `<p>${esc(j.fields['clinic.name'])}</p>`,
  ].join('');
}
return [{ json: { ...j, ok: true, to, subject, html } }];

const sent = $input.first().json;
const req = $('Build email').item.json;
const ok = !!(sent && (sent.id || sent.threadId)) && !sent.error;
return [{ json: {
  alert_instance_id: req.alert_instance_id,
  action_type: 'SEND_EMAIL',
  result_status: ok ? 'SUCCESS' : 'FAILED',
  result_message: ok ? `Email a ${req.to}` : `Email a ${req.to} falló: ${sent?.error?.message || sent?.error || 'sin respuesta de Gmail'}`,
  action_data: { to: req.to, user_id: req.recipient?.user_id, message_id: sent?.id || null },
} }];

const j = $json;
return [{ json: {
  alert_instance_id: j.alert_instance_id,
  action_type: 'SEND_EMAIL',
  result_status: 'FAILED',
  result_message: j.reason,
  action_data: { user_id: j.recipient?.user_id },
} }];

// Variables de la plantilla WHATSAPP (variables_schema: { variable_meta: clave })
// con las claves de staff_dispatch.fields. Respeta el modo prueba de WhatsApp
// (whatsapp_test_mode_enabled / whatsapp_test_phone_whitelist) y el canal de la categoría.
const j = $json;
const cfg = j.config || {};
const fail = (reason) => [{ json: { ...j, ok: false, reason } }];
if (!j.channel_enabled) return fail(`El canal WhatsApp está deshabilitado para la categoría "${j.category_slug}"`);
const tpl = j.template;
if (!tpl || !tpl.code) return fail('Plantilla de WhatsApp inactiva o inexistente');
const digits = String(j.recipient?.phone || '').replace(/\D/g, '');
if (!digits) return fail(`${j.recipient?.name || j.recipient?.user_id}: sin teléfono`);
const phone = '+' + digits;
if (cfg.whatsapp_test_mode) {
  const whitelist = String(cfg.whatsapp_test_whitelist || '').split(',').map((p) => '+' + String(p).trim().replace(/\D/g, '')).filter((p) => p !== '+');
  if (!whitelist.includes(phone)) return fail(`Modo prueba de WhatsApp: ${phone} no está en la lista permitida`);
}
const schema = tpl.variables_schema || {};
const parameters = [];
for (const [name, key] of Object.entries(schema)) {
  if (!(key in j.fields)) return fail(`La plantilla ${tpl.code} usa la clave desconocida "${key}"`);
  parameters.push({ type: 'text', parameter_name: name, text: String(j.fields[key] || '-') });
}
return [{ json: {
  ...j, ok: true, phone,
  body: {
    from: $env.YCLOUD_WHATSAPP_FROM || '+59894024661',
    to: phone,
    type: 'template',
    template: { name: tpl.code, language: { code: tpl.language || 'es' }, components: parameters.length ? [{ type: 'body', parameters }] : [] },
  },
} }];

const res = $input.first().json;
const req = $('Build WhatsApp').item.json;
const ok = !!res && !res.error && !!(res.id || res.wamid || res.status);
return [{ json: {
  alert_instance_id: req.alert_instance_id,
  action_type: 'SEND_WHATSAPP',
  result_status: ok ? 'SUCCESS' : 'FAILED',
  result_message: ok ? `WhatsApp a ${req.phone} (${res.status || 'sent'})` : `WhatsApp a ${req.phone} falló: ${res?.error?.message || JSON.stringify(res?.error || res).slice(0, 300)}`,
  action_data: { phone: req.phone, user_id: req.recipient?.user_id, template: req.template?.code, message_id: res?.id || null },
} }];

const j = $json;
return [{ json: {
  alert_instance_id: j.alert_instance_id,
  action_type: 'SEND_WHATSAPP',
  result_status: 'FAILED',
  result_message: j.reason,
  action_data: { user_id: j.recipient?.user_id },
} }];
